package com.badrulamin.University_Management.repository;  import com.badrulamin.University_Management.entity.AdmissionCampaign; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Repository;  import java.util.List;  @Repository public interface AdmissionCampaignRepository extends JpaRepository<AdmissionCampaign, Long> {     Page<AdmissionCampaign> findByStatus(String status, Pageable pageable);      List<AdmissionCampaign> findBySession_Id(Long sessionId);      List<AdmissionCampaign> findByType(String type);      long countByStatus(String status); }